`timescale 1ns/1ps
// Full IF -> six independent searches -> tracking -> NH -> serial navigation.
// Six equal-amplitude, noise-free PRNs at Fs/4, quantized to the four IF levels.
// The PRN table is generated by the independent Python reference model.
module tb_six_signal;
  logic clk=0,rst_n=0,cfg_valid=0,cfg_enable=1;
  always #30.5474095 clk=~clk;
  logic [2:0] cfg_channel=0;
  logic [5:0] cfg_prn=6;
  logic [1:0] IF=0;
  logic [5:0] capture_ok,bit_sync_ok,nav_data,nav_valid;
  logic chips[0:12275];
  localparam logic [19:0] NH=20'b00000100110101001110;
  longint n=0;
  integer checked[6], polarity[6];
  integer composite, level, sm, bit_id, previous_valid=0;
  bds_bb_6ch_core dut (
    .clk(clk),.rst_n(rst_n),.IF(IF),.cfg_valid(cfg_valid),
    .cfg_channel(cfg_channel),.cfg_enable(cfg_enable),.cfg_prn(cfg_prn),
    .cfg_dop_min(32'sd0),.cfg_dop_step(32'sd0),.cfg_bins(8'd1),
    .capture_ok(capture_ok),.bit_sync_ok(bit_sync_ok),.nav_data(nav_data),.nav_valid(nav_valid));
  function automatic bit data_bit(input integer c,input integer b);
    return ((b*7+c*3)%11)<5;
  endfunction
  function automatic integer offset_samples(input integer c);
    return 8*(123+c*211);
  endfunction
  always @(negedge clk) if(rst_n) begin
    composite=0;
    for(int c=0;c<6;c++) begin
      sm=int'((n+1+offset_samples(c))%16368);
      bit_id=int'((n+1+offset_samples(c))/327360);
      if(chips[c*2046+sm/8] ^ NH[19-int'(((n+1+offset_samples(c))/16368)%20)] ^ data_bit(c,bit_id))
        composite++;
      else composite--;
    end
    case((n+1)%4)
      0: level=composite*3;
      1: level=composite;
      2: level=-composite*3;
      3: level=-composite;
    endcase
    if(level>=4) IF=2'b11;
    else if(level>=0) IF=2'b10;
    else if(level> -4) IF=2'b01;
    else IF=2'b00;
  end
  always @(posedge clk) if(rst_n) n<=n+1;
  always @(negedge clk) if(rst_n) begin
    if(n%1636800==0) $display("STREAM n=%0d capture=%b sync=%b",n,capture_ok,bit_sync_ok);
    if((nav_valid & previous_valid)!=0) $fatal(1,"nav_valid wider than one cycle");
    previous_valid=nav_valid;
    for(int c=0;c<6;c++) if(nav_valid[c]) begin
      bit_id=int'((n+offset_samples(c))/327360)-1;
      if(polarity[c]<0) polarity[c]=int'(nav_data[c])^int'(data_bit(c,bit_id));
      if((int'(nav_data[c])^polarity[c])!=int'(data_bit(c,bit_id)))
        $fatal(1,"real IF nav mismatch ch=%0d bit=%0d got=%0d",c,bit_id,nav_data[c]);
      checked[c]++;
    end
  end
  initial begin
    $readmemh("sim/prn_reference.hex",chips);
    for(int c=0;c<6;c++) begin checked[c]=0;polarity[c]=-1;end
    repeat(4) @(negedge clk);rst_n=1;
    for(int c=0;c<6;c++) begin
      @(negedge clk);cfg_valid=1;cfg_channel=3'(c);cfg_prn=6'(c+6);
      @(negedge clk);cfg_valid=0;
    end
    wait(n>=16368000);
    @(negedge clk);
    if(capture_ok!==6'b111111 || bit_sync_ok!==6'b111111) $fatal(1,"six real signals did not synchronize");
    for(int c=0;c<6;c++) begin
      $display("REAL_IF CHANNEL %0d NAV_BITS %0d POLARITY %0d",c,checked[c],polarity[c]);
      if(checked[c]<15) $fatal(1,"too few real IF bits");
    end
    $display("TEST PASSED");$finish;
  end
  initial begin #1100000000;$fatal(1,"six-signal timeout");end
endmodule
